package ai.taskforge.api;
import ai.taskforge.domain.*; import ai.taskforge.repo.UserRepository; import ai.taskforge.security.JwtService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users;private final PasswordEncoder passwords;private final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;} record Credentials(@Email String email,@Size(min=8) String password,@Size(min=2,max=100) String displayName){} record AuthResponse(String token,String name,String role){} @PostMapping("/login") AuthResponse login(@Valid @RequestBody Credentials c){var u=users.findByEmail(c.email()).orElseThrow(()->new ApiException("INVALID_CREDENTIALS","Invalid email or password."));if(!passwords.matches(c.password(),u.getPasswordHash()))throw new ApiException("INVALID_CREDENTIALS","Invalid email or password.");return new AuthResponse(jwt.issue(u.getId(),u.getEmail(),u.getRole().name()),u.getDisplayName(),u.getRole().name());} @PostMapping("/register") AuthResponse register(@Valid @RequestBody Credentials c){if(users.findByEmail(c.email()).isPresent())throw new ApiException("EMAIL_EXISTS","This email is already registered.");var u=users.save(new AppUser(c.email(),passwords.encode(c.password()),c.displayName(),Role.EMPLOYEE));return new AuthResponse(jwt.issue(u.getId(),u.getEmail(),u.getRole().name()),u.getDisplayName(),u.getRole().name());} }
